charts.query:
// Charts: Highcharts is loaded on the map pages. Put a container in the panel, draw in
// afterCalc (the panel exists by then), and replace the chart on the next round.
[
  {
    title: "Geology - share by era",
    name: "CSR:geologia",
    source: "calculate",
    opacity: 0.8,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{loadjson|id=areas|url=/theme/app/data/geologia_area.json}}" +
      '<div id="era_chart" style="width:290px;height:240px"></div>',
    // afterCalc runs once the expression's values are computed, so the layer needs one
