// Here elevation is reclassified into three classes with a legend set in beforeCalc.
[
  {
    title: "Elevation classes",
    name: "CSR:altimetria",
    source: "calculate",
    opacity: 0.85,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml: "{{legendhtml}}",
    beforeCalc: function () {
      this.setCalculateLegend([
        { color: [39, 174, 96], value: 1, title: "Lowlands (below 300 m)" },
        { color: [241, 196, 15], value: 2, title: "Uplands (300 - 1000 m)" },
        { color: [160, 82, 45], value: 3, title: "Highlands (above 1000 m)" },
