offline-areas.query:
// Offline areas: ExtjsUtils.OFFLINE downloads an area's tiles for use without a connection.
// Estimating first costs nothing - it only counts the tiles of the chosen layers and zooms.
[
  {
    title: "Offline areas",
    name: "CSR:estados",
    source: "calculate",
    opacity: 0.5,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{button|id=estimate_area|text=How many tiles is this view?|handler=estimate}}" +
      "{{label|id=estimate_label|text=Press the button to estimate.}}",
    functions: {
      estimate: function () {
        var map = ExtjsUtils.JS.getMap();
        var zoom = map.getZoom();
        var layers = ExtjsUtils.OFFLINE.getCacheableLayers();
        var tiles = ExtjsUtils.OFFLINE.estimateTileCountForLayers(map.getExtent(), zoom, zoom + 2, layers);
        Ext.getCmp("estimate_label").setText(
          "This view at zoom " + zoom + "-" + (zoom + 2) + ": " + tiles + " tiles for " + layers.length + " layer(s)."
        );
      },
    },
  },
];

overlay-layer.query:
