range-slider-widget.query:
// Range slider: two thumbs (values=[low, high]); the slider's value is the [low, high] pair.
// Here it keeps the places whose average annual rainfall falls inside the band.
[
  {
    title: "Rainfall band",
    name: "CSR:precip_annual_average",
    source: "calculate",
    opacity: 0.85,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{label|text=Annual rainfall (mm)}}" +
      "{{slider|id=band|minValue=300|maxValue=2100|increment=50|values=[800,1100]|width=250}}",
    beforeCalc: function (inputs) {
      var band = inputs.id["band"];
      this.setCalculateLegend([
        { color: [41, 128, 185], value: 1, title: "Between " + band[0] + " and " + band[1] + " mm" },
      ]);
    },
    expression: function (layersVals, inputs) {
      var band = inputs[0]; // [low, high]
      return layersVals[0] >= band[0] && layersVals[0] <= band[1] ? 1 : this.nullValue;
    },
  },
];

