zoomlevel-widget.query:
// ZoomLevel: renders nothing; it hands the map zoom to the layer and recalculates when the
// zoom changes. Here beforeCalc writes it into a label.
[
  {
    title: "Zoom-aware layer",
    name: "CSR:altimetria",
    source: "calculate",
    opacity: 0.85,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml: "{{zoomlevel|id=z}}{{label|id=zoom_label|text=Zoom level: ...}}",
    beforeCalc: function (inputs) {
      var label = Ext.getCmp("zoom_label");
      if (label) label.setText("Zoom level: " + inputs.id["z"] + " - zoom in for full detail");
    },
    expression: function (layersVals, inputs) {
      // coarse 500 m classes when zoomed out, full detail when zoomed in
      return inputs[0] < 7 ? Math.round(layersVals[0] / 500) * 500 : layersVals[0];
    },
  },
];
